async function findDirectByAddress(address){return (await conversations()).find(c=>c.type==='direct'&&c.peerAddress===address)||null}
async function ensureDirectConversation(user){const address=userAddress(user);let conv=await findDirectByAddress(address),snapshot={peerAddress:address,peerUserName:user.userName||'',peerDisplayName:displayNameFor(user),peerEmail:normalizeEmail(user.email||''),peerPhone:userPhone(user),peerPublicKeyJwk:messagingOf(user).publicKeyJwk||null,peerPhotoFileId:String(user.profilePhotoFileId||''),peerAccent:String(user.profileAccent||'#2563eb')};if(conv){Object.assign(conv,snapshot);await saveConversationLocal(conv);return conv}conv=normalizeConversation({id:uid('CHAT'),type:'direct',...snapshot,messages:[],createdAt:iso(),updatedAt:iso()});await saveContactUser(user,{source:'conversation'});await persistConversation(conv);return conv}
async function myMessageIdentity(){const id=await ensureIdentity();return {address:id.address,userName:await myUserName(),displayName:await myDisplayName()}}
async function buildOutgoingMessage(text='',share=null){const me=await myMessageIdentity();return normalizeMessage({id:uid('MSG'),senderAddress:me.address,senderUserName:me.userName,senderDisplayName:me.displayName,text:String(text||''),share,createdAt:iso()})}
async function myContactCard(){const id=await ensureIdentity(),users=await storeUsers(),me=await findMe(users);return contactFromUser(me||{userName:await myUserName(),profileDisplayName:await myDisplayName(),email:await myEmail(),phoneNumber:await setting('personalPhoneNumber',''),messaging:{address:id.address,publicKeyJwk:id.publicKeyJwk,ready:true}},{address:id.address,publicKeyJwk:id.publicKeyJwk,ready:true,source:'conversation'})}
async function sendDirect(user,text='',share=null){const conv=await ensureDirectConversation(user),msg=await buildOutgoingMessage(text,share);conv.messages.push(msg);conv.updatedAt=msg.createdAt;conv.unread=0;await persistConversation(conv);await setSetting(LAST_KEY,conv.id);await sendEnvelopeToUser(user,{kind:'direct-message',message:msg,from:await myContactCard()},{kind:'direct-message',messageId:msg.id});refreshOpenUI(conv.id);return conv}

async function partiesFolder(){return (await ensureRelay()).parties}
async function partyFileById(partyId){const root=await partiesFolder(),files=await listFiles(`'${qEscape(root.id)}' in parents and trashed = false`);return files.find(x=>x.appProperties?.partyId===partyId)||null}
