async function syncMyParties(){
  const id=await ensureIdentity(),root=await partiesFolder(),files=await listFiles(`'${qEscape(root.id)}' in parents and trashed = false`),rows=await conversations(),map=new Map(rows.map(c=>[c.id,c]));
  for(const f of files){
    try{
      const p={...JSON.parse(await fetchText(f.id)),fileId:f.id};
      if(p.kind==='call'&&!p.permanentCall)continue;
      if(!Array.isArray(p.members)||!p.members.some(m=>m.address===id.address))continue;
      let conv=rows.find(c=>c.type==='party'&&c.partyId===p.id);
      const meta={partyId:p.id,partyName:p.name,partyFileId:f.id,partyKind:p.kind==='call'?'call':'chat',permanentCall:!!p.permanentCall,storeManaged:!!p.storeManaged,ownerAddress:String(p.ownerAddress||''),adminAddresses:Array.isArray(p.adminAddresses)?p.adminAddresses:[],members:p.members};
      if(!conv)conv=normalizeConversation({id:uid('PARTYCHAT'),type:'party',...meta,messages:[],createdAt:p.createdAt||iso(),updatedAt:p.updatedAt||iso()});else Object.assign(conv,meta);
      map.set(conv.id,conv)
    }catch{}
  }
  const out=[...map.values()].sort((a,b)=>(Date.parse(b.updatedAt)||0)-(Date.parse(a.updatedAt)||0));await setSetting(CONV_KEY,out);return out
}
async function createParty(name,memberUsers,options={}){
  const meId=await ensureIdentity(),meUser=await findMe(await storeUsers()),me={address:meId.address,userName:meUser?.userName||await myUserName(),displayName:displayNameFor(meUser||{userName:await myUserName()}),joinedAt:iso()},members=[me,...memberUsers.filter(userReady).map(u=>({address:userAddress(u),userName:u.userName||'',displayName:displayNameFor(u),email:normalizeEmail(u.email||''),phoneNumber:userPhone(u),joinedAt:iso()}))],kind=options.kind==='call'?'call':'chat',permanentCall=kind==='call'&&!!options.permanentCall,storeManaged=!!options.storeManaged,adminAddresses=[meId.address];const uniq=[...new Map(members.map(m=>[m.address,m])).values()],party=await saveParty({id:uid('PARTY'),name:String(name||'LotKeys Group').trim().slice(0,60)||'LotKeys Group',kind,permanentCall,storeManaged,ownerAddress:meId.address,adminAddresses,members:uniq,createdAt:iso()});const createdText=kind==='call'?`Created the ${permanentCall?'permanent ':'temporary '}Group Call “${party.name}”`:`Created the Group Chat “${party.name}”`,conv=normalizeConversation({id:uid('PARTYCHAT'),type:'party',partyId:party.id,partyName:party.name,partyFileId:party.fileId,partyKind:kind,permanentCall,storeManaged,ownerAddress:party.ownerAddress,adminAddresses:party.adminAddresses,members:party.members,messages:[normalizeMessage({id:uid('SYS'),senderAddress:meId.address,senderDisplayName:me.displayName,text:createdText,system:true,createdAt:iso()})],createdAt:iso(),updatedAt:iso()});if(kind==='chat'||permanentCall)await persistConversation(conv);for(const u of memberUsers.filter(userReady)){await sendEnvelopeToUser(u,{kind:'party-invite',party:{id:party.id,name:party.name,fileId:party.fileId,kind,permanentCall,storeManaged,ownerAddress:party.ownerAddress,adminAddresses:party.adminAddresses,members:party.members,createdAt:party.createdAt},invitedBy:me},{kind:'party-invite',partyId:party.id}).catch(console.warn)}if(kind==='chat'||permanentCall)await setSetting(LAST_KEY,conv.id);return conv
}
async function sendParty(conv,text='',share=null){let party=await loadParty(conv.partyId,conv.partyFileId);if(!party)throw new Error('This Group is no longer available.');const me=await myMessageIdentity(),msg=await buildOutgoingMessage(text,share);conv.members=party.members||conv.members;conv.partyName=party.name||conv.partyName;conv.messages.push(msg);conv.unread=0;await persistConversation(conv);const users=await storeUsers();for(const member of party.members||[]){if(member.address===me.address)continue;const u=findUserByAddress(users,member.address);if(!u||!userReady(u))continue;await sendEnvelopeToUser(u,{kind:'party-message',partyId:party.id,partyName:party.name,partyFileId:party.fileId,members:party.members,message:msg},{kind:'party-message',messageId:msg.id,partyId:party.id}).catch(console.warn)}await setSetting(LAST_KEY,conv.id);refreshOpenUI(conv.id);return conv}

