async function pollInbox(){if(pollBusy)return;pollBusy=true;try{const st=await DriveSync.getStatus();if(!st.connected||!await setting('personalProfileDriveFolderId',''))return;const id=await ensureIdentity(),inbox=await inboxFolder(id.address),files=(await listFiles(`'${qEscape(inbox.id)}' in parents and trashed = false`)).slice(0,RELAY_LIMIT);await loadProcessedRelayIds();for(const file of files){try{if(processedRelayIds.has(String(file.id))){await deleteRelayFile(file);continue}const env=JSON.parse(await fetchText(file.id));if(env.toAddress!==id.address){continue}const payload=await decryptEnvelope(env,id.privateKeyJwk);await handleIncomingPayload(payload,file);await markRelayProcessed(file.id);await deleteRelayFile(file)}catch(err){console.warn('Could not process one incoming LotKeys message',err);if(/decrypt|operation|key/i.test(String(err?.message||err)))await deleteRelayFile(file).catch(()=>{})}}}catch(err){console.warn('Message check deferred',err)}finally{pollBusy=false}}
